<p>
<script>
(function() {
  const RETOS_TRI8 = [
    {
      nombre: 'Triángulo 1',
      datos: 'Lados: 7 cm · 7 cm · 7 cm | Ángulos: 60° · 60° · 60°',
      pts: [[170, 38], [82, 192], [258, 192]],
      lado: 'equilatero',
      ang: 'acutangulo',
      explicacion: 'Tiene los 3 lados iguales (equilátero) y los 3 ángulos menores de 90° (acutángulo).'
    },
    {
      nombre: 'Triángulo 2',
      datos: 'Lados: 6 cm · 8 cm · 10 cm | Forma un ángulo de 90°',
      pts: [[85, 195], [85, 55], [265, 195]],
      lado: 'escaleno',
      ang: 'rectangulo',
      recto: [85, 195],
      explicacion: 'Los 3 lados tienen distinta medida (escaleno) y tiene un ángulo recto de 90° (rectángulo).'
    },
    {
      nombre: 'Triángulo 3',
      datos: 'Lados: 6 cm · 6 cm · 5 cm | Todos sus ángulos son agudos',
      pts: [[170, 42], [98, 192], [242, 192]],
      lado: 'isosceles',
      ang: 'acutangulo',
      explicacion: 'Tiene 2 lados iguales y 1 desigual (isósceles) y todos sus ángulos son menores de 90° (acutángulo).'
    },
    {
      nombre: 'Triángulo 4',
      datos: 'Lados: 5 cm · 7 cm · 10 cm | Un ángulo mayor de 90°',
      pts: [[65, 190], [125, 85], [285, 190]],
      lado: 'escaleno',
      ang: 'obtusangulo',
      explicacion: 'Sus 3 lados son distintos (escaleno) y tiene un ángulo obtuso mayor de 90° (obtusángulo).'
    },
    {
      nombre: 'Triángulo 5',
      datos: 'Lados: 5 cm · 5 cm · 7 cm | Forma un ángulo de 90°',
      pts: [[105, 195], [105, 75], [225, 195]],
      lado: 'isosceles',
      ang: 'rectangulo',
      recto: [105, 195],
      explicacion: 'Los dos catetos miden igual (isósceles) y forman un ángulo recto de 90° (rectángulo).'
    }
  ];

  let idx8 = 0;

  function cargarTri8(idx) {
    idx8 = idx;
    const r = RETOS_TRI8[idx];

    document.getElementById('ct8-titulo').textContent = r.nombre;
    document.getElementById('ct8-datos').textContent = r.datos;
    document.getElementById('ct8-sel-lado').value = '';
    document.getElementById('ct8-sel-ang').value = '';
    document.getElementById('ct8-sel-lado').style.borderColor = '#cbd5e1';
    document.getElementById('ct8-sel-ang').style.borderColor = '#cbd5e1';
    document.getElementById('ct8-feedback').textContent = '';

    const capa = document.getElementById('capa-clas-tri-8');
    capa.innerHTML = '';

    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('points', r.pts.map(p => p.join(',')).join(' '));
    poly.setAttribute('fill', '#fef08a');
    poly.setAttribute('stroke', '#0f172a');
    poly.setAttribute('stroke-width', '2.5');
    poly.setAttribute('stroke-linejoin', 'round');
    capa.appendChild(poly);

    if (r.recto) {
      const [rx, ry] = r.recto;
      const esc = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
      esc.setAttribute('points', `${rx},${ry - 15} ${rx + 15},${ry - 15} ${rx + 15},${ry}`);
      esc.setAttribute('fill', 'none');
      esc.setAttribute('stroke', '#b45309');
      esc.setAttribute('stroke-width', '2.5');
      capa.appendChild(esc);
    }
  }

  window.comprobarClasTri8 = function() {
    const r = RETOS_TRI8[idx8];
    const vL = document.getElementById('ct8-sel-lado').value;
    const vA = document.getElementById('ct8-sel-ang').value;
    const fb = document.getElementById('ct8-feedback');

    const okL = vL === r.lado;
    const okA = vA === r.ang;

    document.getElementById('ct8-sel-lado').style.borderColor = okL ? '#16a34a' : '#dc2626';
    document.getElementById('ct8-sel-ang').style.borderColor = okA ? '#16a34a' : '#dc2626';

    if (okL && okA) {
      fb.style.color = '#15803d';
      fb.textContent = `¡Correcto! ${r.explicacion}`;
    } else {
      fb.style.color = '#dc2626';
      fb.textContent = 'Revisa los criterios marcados en rojo: compara las longitudes de los lados y fíjate si algún ángulo es de 90°, menor de 90° o mayor de 90°.';
    }
  };

  window.siguienteClasTri8 = function() {
    cargarTri8((idx8 + 1) % RETOS_TRI8.length);
  };

  cargarTri8(0);
})();
</script>
