<div role="button" onclick="cargarTrianguloPitagoras(1)" id="btn-tri-1" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #0284c7; color: #ffffff;" tabindex="0">Lados 6, 8 y 10</div>
<div role="button" onclick="cargarTrianguloPitagoras(2)" id="btn-tri-2" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">Lados 5, 12 y 13</div>
