<!-- Marcador visual de áreas y relación -->
<div id="marcador-pitagoras" style="margin-top: 14px; background-color: #f0f9ff; border-left: 5px solid #0284c7; border-radius: 6px; padding: 14px 16px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px;">
