<div id="puzzle-pitagoras-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"></div>
<p>
<script>
(function() {
  const TRIANGULOS = [
    { a: 3, b: 4, c: 5 },
    { a: 6, b: 8, c: 10 },
    { a: 5, b: 12, c: 13 }
  ];

  // Vértice del ángulo recto de 90º
  const OX = 280;
  const OY = 320;

  let triActual = TRIANGULOS[1];
  let idxTri = 1;
  let tamCelda = 20;
  let fichas = [];
  let fichaActiva = null;
  let offset = { x: 0, y: 0 };

  function getAnguloHipotenusaDeg() {
    const s = tamCelda;
    const { a, b } = triActual;
    const dx = b * s;
    const dy = a * s;
    return Math.atan2(dy, dx) * (180 / Math.PI);
  }

  function getSVGPoint(e) {
    const svg = document.getElementById('svg-puzzle-pitagoras');
    const pt = svg.createSVGPoint();
    if (e.touches && e.touches.length > 0) {
      pt.x = e.touches[0].clientX;
      pt.y = e.touches[0].clientY;
    } else {
      pt.x = e.clientX;
      pt.y = e.clientY;
    }
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  window.cargarTrianguloPitagoras = function(indice) {
    idxTri = indice;
    triActual = TRIANGULOS[indice];

    const maxLado = Math.max(triActual.a, triActual.b, triActual.c);
    tamCelda = maxLado >= 12 ? 14 : (maxLado >= 10 ? 20 : 25);

    for (let i = 0; i < TRIANGULOS.length; i++) {
      const btn = document.getElementById('btn-tri-' + i);
      if (i === indice) {
        btn.style.backgroundColor = '#0284c7';
        btn.style.color = '#ffffff';
      } else {
        btn.style.backgroundColor = '#ffffff';
        btn.style.color = '#0369a1';
      }
    }

    reiniciarPuzzlePitagoras();
  };

  function crearFichas() {
    fichas = [];
    const s = tamCelda;
    const { a, b } = triActual;

    // Cuadrado sobre cateto a (izquierda)
    const sqAX = OX - a * s;
    const sqAY = OY - a * s;
    for (let r = 0; r < a; r++) {
      for (let col = 0; col < a; col++) {
        fichas.push({
          tipo: 'a',
          homeX: sqAX + col * s,
          homeY: sqAY + r * s,
          x: sqAX + col * s,
          y: sqAY + r * s,
          rot: 0,
          enHipotenusa: false
        });
      }
    }

    // Cuadrado sobre cateto b (abajo)
    const sqBX = OX;
    const sqBY = OY;
    for (let r = 0; r < b; r++) {
      for (let col = 0; col < b; col++) {
        fichas.push({
          tipo: 'b',
          homeX: sqBX + col * s,
          homeY: sqBY + r * s,
          x: sqBX + col * s,
          y: sqBY + r * s,
          rot: 0,
          enHipotenusa: false
        });
      }
    }
  }

  function calcularHuecosHipotenusa() {
    const s = tamCelda;
    const { a, b, c } = triActual;
    const x1 = OX;
    const y1 = OY - a * s;
    const x2 = OX + b * s;
    const y2 = OY;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const nx = dy;
    const ny = -dx;

    const huecos = [];
    for (let i = 0; i < c; i++) {
      for (let j = 0; j < c; j++) {
        const cx = x1 + ((i + 0.5) / c) * dx + ((j + 0.5) / c) * nx;
        const cy = y1 + ((i + 0.5) / c) * dy + ((j + 0.5) / c) * ny;
        huecos.push({ x: cx, y: cy });
      }
    }
    return huecos;
  }

  function puntoEnCuadradoHipotenusa(px, py) {
    const s = tamCelda;
    const { a, b, c } = triActual;
    const x1 = OX;
    const y1 = OY - a * s;
    const x2 = OX + b * s;
    const y2 = OY;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const nx = dy;
    const ny = -dx;
    const len2 = c * s * c * s;

    const relX = px - x1;
    const relY = py - y1;

    // Proyecciones normalizadas [0..1] sobre los dos lados del cuadrado C
    const u = (relX * dx + relY * dy) / len2;
    const v = (relX * nx + relY * ny) / len2;

    return u >= -0.08 && u <= 1.08 && v >= -0.08 && v <= 1.08;
  }

  function dibujarEscena() {
    const s = tamCelda;
    const { a, b, c } = triActual;
    const ladoFicha = Math.max(8, s - 2.5);

    const capaA = document.getElementById('capa-cuadrado-a');
    const capaB = document.getElementById('capa-cuadrado-b');
    const capaC = document.getElementById('capa-cuadrado-c');
    const capaTri = document.getElementById('capa-triangulo');
    const capaFichas = document.getElementById('capa-fichas');

    capaA.innerHTML = '';
    capaB.innerHTML = '';
    capaC.innerHTML = '';
    capaTri.innerHTML = '';
    capaFichas.innerHTML = '';

    // 1. Cuadrado A
    const sqAX = OX - a * s;
    const sqAY = OY - a * s;
    const rectA = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rectA.setAttribute('x', sqAX);
    rectA.setAttribute('y', sqAY);
    rectA.setAttribute('width', a * s);
    rectA.setAttribute('height', a * s);
    rectA.setAttribute('fill', '#e0f2fe');
    rectA.setAttribute('stroke', '#0284c7');
    rectA.setAttribute('stroke-width', '2');
    capaA.appendChild(rectA);

    for (let i = 1; i < a; i++) {
      const l1 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      l1.setAttribute('x1', sqAX + i * s); l1.setAttribute('y1', sqAY);
      l1.setAttribute('x2', sqAX + i * s); l1.setAttribute('y2', sqAY + a * s);
      l1.setAttribute('stroke', '#bae6fd'); l1.setAttribute('stroke-width', '1');
      capaA.appendChild(l1);

      const l2 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      l2.setAttribute('x1', sqAX); l2.setAttribute('y1', sqAY + i * s);
      l2.setAttribute('x2', sqAX + a * s); l2.setAttribute('y2', sqAY + i * s);
      l2.setAttribute('stroke', '#bae6fd'); l2.setAttribute('stroke-width', '1');
      capaA.appendChild(l2);
    }

    // 2. Cuadrado B
    const sqBX = OX;
    const sqBY = OY;
    const rectB = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rectB.setAttribute('x', sqBX);
    rectB.setAttribute('y', sqBY);
    rectB.setAttribute('width', b * s);
    rectB.setAttribute('height', b * s);
    rectB.setAttribute('fill', '#dcfce7');
    rectB.setAttribute('stroke', '#16a34a');
    rectB.setAttribute('stroke-width', '2');
    capaB.appendChild(rectB);

    for (let i = 1; i < b; i++) {
      const l1 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      l1.setAttribute('x1', sqBX + i * s); l1.setAttribute('y1', sqBY);
      l1.setAttribute('x2', sqBX + i * s); l1.setAttribute('y2', sqBY + b * s);
      l1.setAttribute('stroke', '#bbf7d0'); l1.setAttribute('stroke-width', '1');
      capaB.appendChild(l1);

      const l2 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      l2.setAttribute('x1', sqBX); l2.setAttribute('y1', sqBY + i * s);
      l2.setAttribute('x2', sqBX + b * s); l2.setAttribute('y2', sqBY + i * s);
      l2.setAttribute('stroke', '#bbf7d0'); l2.setAttribute('stroke-width', '1');
      capaB.appendChild(l2);
    }

    // 3. Cuadrado C (sobre la hipotenusa)
    const x1 = OX;
    const y1 = OY - a * s;
    const x2 = OX + b * s;
    const y2 = OY;
    const dx = x2 - x1;
    const dy = y2 - y1;
    const nx = dy;
    const ny = -dx;

    const polyC = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    polyC.setAttribute('points', `${x1},${y1} ${x2},${y2} ${x2 + nx},${y2 + ny} ${x1 + nx},${y1 + ny}`);
    polyC.setAttribute('fill', '#fff7ed');
    polyC.setAttribute('stroke', '#ea580c');
    polyC.setAttribute('stroke-width', '2.2');
    capaC.appendChild(polyC);

    for (let i = 1; i < c; i++) {
      const frac = i / c;
      const ax = x1 + dx * frac;
      const ay = y1 + dy * frac;
      const bx = ax + nx;
      const by = ay + ny;
      const la = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      la.setAttribute('x1', ax); la.setAttribute('y1', ay);
      la.setAttribute('x2', bx); la.setAttribute('y2', by);
      la.setAttribute('stroke', '#fed7aa'); la.setAttribute('stroke-width', '1');
      capaC.appendChild(la);

      const cx = x1 + nx * frac;
      const cy = y1 + ny * frac;
      const dx2 = cx + dx;
      const dy2 = cy + dy;
      const lb = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      lb.setAttribute('x1', cx); lb.setAttribute('y1', cy);
      lb.setAttribute('x2', dx2); lb.setAttribute('y2', dy2);
      lb.setAttribute('stroke', '#fed7aa'); lb.setAttribute('stroke-width', '1');
      capaC.appendChild(lb);
    }

    // 4. Triángulo rectángulo y ángulo de 90º
    const tri = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    tri.setAttribute('points', `${OX},${OY} ${OX},${OY - a * s} ${OX + b * s},${OY}`);
    tri.setAttribute('fill', '#fef08a');
    tri.setAttribute('fill-opacity', '0.85');
    tri.setAttribute('stroke', '#0f172a');
    tri.setAttribute('stroke-width', '2.5');
    capaTri.appendChild(tri);

    const ang = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    ang.setAttribute('points', `${OX},${OY - 13} ${OX + 13},${OY - 13} ${OX + 13},${OY}`);
    ang.setAttribute('fill', 'none');
    ang.setAttribute('stroke', '#0f172a');
    ang.setAttribute('stroke-width', '2');
    capaTri.appendChild(ang);

    // 5. Fichas arrastrables (rotadas alrededor de su centro)
    fichas.forEach((f, idx) => {
      const centroX = f.x + s / 2;
      const centroY = f.y + s / 2;
      const xTopLeft = centroX - ladoFicha / 2;
      const yTopLeft = centroY - ladoFicha / 2;

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', xTopLeft);
      rect.setAttribute('y', yTopLeft);
      rect.setAttribute('width', ladoFicha);
      rect.setAttribute('height', ladoFicha);
      rect.setAttribute('rx', Math.max(2, ladoFicha * 0.14));
      rect.setAttribute('fill', f.tipo === 'a' ? '#38bdf8' : '#4ade80');
      rect.setAttribute('stroke', f.tipo === 'a' ? '#0369a1' : '#15803d');
      rect.setAttribute('stroke-width', '1.6');
      rect.setAttribute('class', 'ficha-pit-cursor');

      if (Math.abs(f.rot) > 0.01) {
        rect.setAttribute('transform', `rotate(${f.rot.toFixed(2)}, ${centroX.toFixed(2)}, ${centroY.toFixed(2)})`);
      }

      rect.addEventListener('mousedown', (e) => iniciarArrastre(e, idx));
      rect.addEventListener('touchstart', (e) => iniciarArrastre(e, idx), { passive: false });

      capaFichas.appendChild(rect);
    });

    actualizarMarcador();
  }

  function iniciarArrastre(e, idx) {
    e.preventDefault();
    const p = getSVGPoint(e);
    const item = fichas.splice(idx, 1)[0];
    fichas.push(item);
    fichaActiva = fichas.length - 1;

    offset.x = p.x - item.x;
    offset.y = p.y - item.y;
    dibujarEscena();
  }

  function moverArrastre(e) {
    if (fichaActiva === null) return;
    e.preventDefault();
    const p = getSVGPoint(e);
    const f = fichas[fichaActiva];
    const s = tamCelda;

    f.x = p.x - offset.x;
    f.y = p.y - offset.y;

    // Girar automáticamente al acercarse/entrar en el cuadrado naranja
    const centroX = f.x + s / 2;
    const centroY = f.y + s / 2;
    f.rot = puntoEnCuadradoHipotenusa(centroX, centroY) ? getAnguloHipotenusaDeg() : 0;

    dibujarEscena();
  }

  function soltarArrastre() {
    if (fichaActiva === null) return;
    const f = fichas[fichaActiva];
    const s = tamCelda;
    const centroX = f.x + s / 2;
    const centroY = f.y + s / 2;

    const huecos = calcularHuecosHipotenusa();
    const ocupados = fichas.filter((other, i) => i !== fichaActiva && other.enHipotenusa);

    let huecoLibre = null;
    let menorDist = s * 1.35;

    huecos.forEach(h => {
      const yaUsado = ocupados.some(o => Math.hypot((o.x + s / 2) - h.x, (o.y + s / 2) - h.y) < s * 0.45);
      if (!yaUsado) {
        const dist = Math.hypot(centroX - h.x, centroY - h.y);
        if (dist < menorDist) {
          menorDist = dist;
          huecoLibre = h;
        }
      }
    });

    if (huecoLibre) {
      f.x = huecoLibre.x - s / 2;
      f.y = huecoLibre.y - s / 2;
      f.rot = getAnguloHipotenusaDeg();
      f.enHipotenusa = true;
    } else {
      f.x = f.homeX;
      f.y = f.homeY;
      f.rot = 0;
      f.enHipotenusa = false;
    }

    fichaActiva = null;
    dibujarEscena();
  }

  window.trasvasarTodoPitagoras = function() {
    const huecos = calcularHuecosHipotenusa();
    const s = tamCelda;
    const angulo = getAnguloHipotenusaDeg();
    fichas.forEach((f, idx) => {
      if (huecos[idx]) {
        f.x = huecos[idx].x - s / 2;
        f.y = huecos[idx].y - s / 2;
        f.rot = angulo;
        f.enHipotenusa = true;
      }
    });
    dibujarEscena();
  };

  window.reiniciarPuzzlePitagoras = function() {
    crearFichas();
    dibujarEscena();
  };

  function actualizarMarcador() {
    const { a, b, c } = triActual;
    const areaA = a * a;
    const areaB = b * b;
    const areaC = c * c;
    const colocadas = fichas.filter(f => f.enHipotenusa).length;

    document.getElementById('info-a').textContent = `${a} u (área = ${areaA})`;
    document.getElementById('info-b').textContent = `${b} u (área = ${areaB})`;
    document.getElementById('info-c').textContent = `${c} u (área = ${areaC})`;

    const estado = document.getElementById('estado-puzzle-pit');
    if (colocadas === areaC) {
      estado.style.color = '#15803d';
      estado.textContent = `¡Completo! ${areaA} + ${areaB} = ${areaC} cuadritos (${a}² + ${b}² = ${c}²)`;
    } else {
      estado.style.color = '#0369a1';
      estado.textContent = `Colocados en la hipotenusa: ${colocadas} de ${areaC} cuadritos`;
    }
  }

  const svg = document.getElementById('svg-puzzle-pitagoras');
  svg.addEventListener('mousemove', moverArrastre);
  svg.addEventListener('mouseup', soltarArrastre);
  svg.addEventListener('mouseleave', soltarArrastre);
  svg.addEventListener('touchmove', moverArrastre, { passive: false });
  svg.addEventListener('touchend', soltarArrastre);

  cargarTrianguloPitagoras(1);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1795276379601-3vszg5lww","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div style="margin: 12px 0 6px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; line-height: 1.55;">
<p style="margin: 0 0 6px 0; font-size: 0.98rem;">Aprende a localizar el ángulo recto de 90° y la hipotenusa en distintas posiciones, y a distinguir cuándo se aplica el Teorema de Pitágoras.</p>
<p style="margin: 0; font-size: 0.95rem; color: #334155;"><strong>Instrucciones:</strong></p>
<ul>
<li style="font-size: 0.95rem; color: #334155;">
<p>En el reto 1, marca primero el <strong>vértice de 90°</strong> y luego haz clic en la <strong>hipotenusa</strong>.</p>
</li>
<li style="font-size: 0.95rem; color: #334155;">
<p>En el reto 2, responde si se puede aplicar Pitágoras directamente y avanza con <em>Siguiente figura</em>.</p>
</li>
</ul>
<hr />
<p style="margin: 0; font-size: 0.95rem; color: #334155;"><br /></p>
</div>
<div id="cazador-pitagoras-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><!-- Selector de modo -->
<div style="display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center;"><span style="font-size: 0.88rem; font-weight: 800; color: #0f172a;">Elige el reto:</span>
<div role="button" onclick="cambiarModoCazador('hipotenusa')" id="btn-modo-hip" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #0284c7; color: #ffffff;" tabindex="0">1. Caza la hipotenusa y los 90°</div>
<div role="button" onclick="cambiarModoCazador('aplica')" id="btn-modo-aplica" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">2. ¿Se puede aplicar Pitágoras?</div>
</div>
<!-- Consigna dinámica -->
<p id="cazador-consigna" style="margin: 0 0 14px 0; font-size: 0.98rem; color: #334155; line-height: 1.5;"></p>
<!-- Escena SVG -->
<div style="width: 100%; max-width: 680px; margin: 0 auto; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden;"><svg id="svg-cazador-pit" viewbox="0 0 640 340" style="width: 100%; height: auto; display: block;"> <rect width="640" height="340" fill="#f8fafc"></rect> <g id="capa-figura-cazador"></g> </svg></div>
<!-- Controles inferiores según el modo -->
<div id="controles-modo-hip" style="margin-top: 12px; display: flex; flex-wrap: wrap; justify-content: center; gap: 10px;">
<div role="button" onclick="setObjetivoCaza('angulo')" id="btn-obj-angulo" style="padding: 7px 14px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0f172a; background-color: #fef08a; color: #0f172a;" tabindex="0">Paso A: Marcar vértice de 90°</div>
<div role="button" onclick="setObjetivoCaza('hipotenusa')" id="btn-obj-hip" style="padding: 7px 14px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #ea580c; background-color: #ffffff; color: #c2410c;" tabindex="0">Paso B: Marcar la hipotenusa</div>
</div>
<div id="controles-modo-aplica" style="display: none; margin-top: 12px; justify-content: center; gap: 12px; flex-wrap: wrap;">
<div role="button" onclick="responderAplica(true)" style="padding: 8px 18px; border-radius: 6px; font-size: 0.92rem; font-weight: 800; cursor: pointer; border: 2px solid #15803d; background-color: #16a34a; color: #ffffff;" tabindex="0">Sí, es triángulo rectángulo</div>
<div role="button" onclick="responderAplica(false)" style="padding: 8px 18px; border-radius: 6px; font-size: 0.92rem; font-weight: 800; cursor: pointer; border: 2px solid #b91c1c; background-color: #ffffff; color: #b91c1c;" tabindex="0">No directamente</div>
</div>
<!-- Retroalimentación y siguiente -->
<div id="cazador-feedback" style="margin-top: 14px; background-color: #f0f9ff; border-left: 5px solid #0284c7; border-radius: 6px; padding: 12px 16px; font-size: 0.95rem; font-weight: bold; color: #0f172a; line-height: 1.5; min-height: 24px;">Selecciona una parte de la figura para empezar.</div>
<div style="margin-top: 12px; display: flex; justify-content: flex-end;">
<div role="button" onclick="nuevoRetoCazador()" style="background-color: #ffffff; border: 2px solid #0284c7; color: #0369a1; font-weight: 800; font-size: 0.88rem; padding: 7px 16px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Siguiente figura →</div>
</div>
</div>
<p>
<script>
(function() {
  let modo = 'hipotenusa';
  let objetivoCaza = 'angulo';
  let anguloMarcado = false;
  let hipMarcada = false;
  let retoActual = null;
  let respondido = false;

  // Construye un triángulo rectángulo EXACTO y lo centra automáticamente en el lienzo 640x340
  function crearTrianguloRectangulo(nombre, cat1, cat2, anguloDeg, explicacion) {
    const rad = anguloDeg * Math.PI / 180;
    const ux = Math.cos(rad);
    const uy = Math.sin(rad);
    const vx = -uy;
    const vy = ux;

    const pRecto = { x: 0, y: 0 };
    const p1 = { x: cat1 * ux, y: cat1 * uy };
    const p2 = { x: cat2 * vx, y: cat2 * vy };

    const raw = [p1, pRecto, p2];
    const minX = Math.min(...raw.map(p => p.x));
    const maxX = Math.max(...raw.map(p => p.x));
    const minY = Math.min(...raw.map(p => p.y));
    const maxY = Math.max(...raw.map(p => p.y));

    const cx = (minX + maxX) / 2;
    const cy = (minY + maxY) / 2;

    const vertices = raw.map(p => ({
      x: Math.round(320 + (p.x - cx)),
      y: Math.round(170 + (p.y - cy))
    }));

    return {
      nombre: nombre,
      vertices: vertices,
      idxRecto: 1,
      hipIdx: 2,
      explicacion: explicacion
    };
  }

  const RETOS_HIPOTENUSA = [
    crearTrianguloRectangulo(
      'Triángulo apoyado sobre su hipotenusa',
      150, 200, 143.13,
      'El ángulo de 90° está en el vértice superior (donde se unen perpendicularmente los catetos). El lado horizontal de abajo, opuesto al ángulo recto, es la hipotenusa.'
    ),
    crearTrianguloRectangulo(
      'Triángulo rectángulo clásico',
      165, 230, -90,
      'El ángulo de 90° está en la esquina inferior izquierda. El lado inclinado opuesto a él es la hipotenusa.'
    ),
    crearTrianguloRectangulo(
      'Triángulo rectángulo boca abajo',
      150, 200, -143.13,
      'Aunque el lado horizontal está arriba, es el lado opuesto al ángulo recto inferior y el más largo: ¡esa es la hipotenusa!'
    ),
    crearTrianguloRectangulo(
      'Triángulo rectángulo girado a la derecha',
      145, 195, 125,
      'El ángulo recto está en el vértice derecho; por tanto, el lado de la izquierda (opuesto a los 90°) es la hipotenusa.'
    ),
    crearTrianguloRectangulo(
      'Triángulo rectángulo alargado',
      115, 240, 90,
      'El ángulo de 90° está en la esquina superior izquierda. Frente a él queda la hipotenusa.'
    )
  ];

  const RETOS_APLICA = [
    {
      nombre: 'Triángulo rectángulo',
      vertices: [{ x: 205, y: 260 }, { x: 205, y: 80 }, { x: 445, y: 260 }],
      esRectangulo: true,
      marcarRecto: 0,
      explicacion: 'Sí: tiene un ángulo recto de 90° entre sus dos catetos, así que podemos aplicar el Teorema de Pitágoras.'
    },
    {
      nombre: 'Triángulo equilátero / acutángulo (tres ángulos de 60°)',
      vertices: [{ x: 210, y: 260 }, { x: 320, y: 70 }, { x: 430, y: 260 }],
      esRectangulo: false,
      explicacion: 'No directamente: todos sus ángulos son agudos (menores de 90°), no tiene ningún ángulo recto.'
    },
    {
      nombre: 'Triángulo obtusángulo (un ángulo mayor de 90°)',
      vertices: [{ x: 170, y: 245 }, { x: 285, y: 145 }, { x: 470, y: 245 }],
      esRectangulo: false,
      explicacion: 'No directamente: el ángulo superior es obtuso (mayor de 90°). Pitágoras solo vale en triángulos rectángulos.'
    },
    {
      nombre: 'Cuadrado dividido por su diagonal',
      vertices: [{ x: 225, y: 75 }, { x: 225, y: 265 }, { x: 415, y: 265 }, { x: 415, y: 75 }],
      diagonal: [1, 3],
      esRectangulo: true,
      explicacion: 'Sí: al partir un cuadrado por su diagonal se forman dos triángulos rectángulos (los ángulos del cuadrado son de 90°).'
    }
  ];

  let idxReto = 0;

  function dibujarMarcaAnguloRecto(capa, vertices, idxRecto) {
    const n = vertices.length;
    const p = vertices[idxRecto];
    const pPrev = vertices[(idxRecto - 1 + n) % n];
    const pNext = vertices[(idxRecto + 1) % n];

    const v1x = pPrev.x - p.x;
    const v1y = pPrev.y - p.y;
    const len1 = Math.hypot(v1x, v1y);

    const v2x = pNext.x - p.x;
    const v2y = pNext.y - p.y;
    const len2 = Math.hypot(v2x, v2y);

    const d = 18;
    const a = { x: p.x + (v1x / len1) * d, y: p.y + (v1y / len1) * d };
    const b = { x: p.x + (v2x / len2) * d, y: p.y + (v2y / len2) * d };
    const c = { x: a.x + (v2x / len2) * d, y: a.y + (v2y / len2) * d };

    const escuadra = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    escuadra.setAttribute('points', `${a.x.toFixed(1)},${a.y.toFixed(1)} ${c.x.toFixed(1)},${c.y.toFixed(1)} ${b.x.toFixed(1)},${b.y.toFixed(1)}`);
    escuadra.setAttribute('fill', 'none');
    escuadra.setAttribute('stroke', '#b45309');
    escuadra.setAttribute('stroke-width', '2.5');
    capa.appendChild(escuadra);
  }

  window.cambiarModoCazador = function(nuevoModo) {
    modo = nuevoModo;
    const btnHip = document.getElementById('btn-modo-hip');
    const btnApl = document.getElementById('btn-modo-aplica');

    if (modo === 'hipotenusa') {
      btnHip.style.backgroundColor = '#0284c7';
      btnHip.style.color = '#ffffff';
      btnApl.style.backgroundColor = '#ffffff';
      btnApl.style.color = '#0369a1';
      document.getElementById('controles-modo-hip').style.display = 'flex';
      document.getElementById('controles-modo-aplica').style.display = 'none';
      document.getElementById('cazador-consigna').innerHTML =
        'Observa el triángulo rectángulo. Marca primero el <strong>vértice de 90°</strong> y luego haz clic sobre la <strong>hipotenusa</strong> (el lado opuesto al ángulo recto).';
    } else {
      btnApl.style.backgroundColor = '#0284c7';
      btnApl.style.color = '#ffffff';
      btnHip.style.backgroundColor = '#ffffff';
      btnHip.style.color = '#0369a1';
      document.getElementById('controles-modo-hip').style.display = 'none';
      document.getElementById('controles-modo-aplica').style.display = 'flex';
      document.getElementById('cazador-consigna').innerHTML =
        'Fíjate en la figura y en sus ángulos: ¿podemos aplicar el <strong>Teorema de Pitágoras</strong> directamente?';
    }
    idxReto = 0;
    nuevoRetoCazador(true);
  };

  window.setObjetivoCaza = function(obj) {
    objetivoCaza = obj;
    const bAng = document.getElementById('btn-obj-angulo');
    const bHip = document.getElementById('btn-obj-hip');
    if (obj === 'angulo') {
      bAng.style.boxShadow = '0 0 0 2px #0284c7';
      bHip.style.boxShadow = 'none';
    } else {
      bHip.style.boxShadow = '0 0 0 2px #0284c7';
      bAng.style.boxShadow = 'none';
    }
  };

  window.nuevoRetoCazador = function(mantenerIndice) {
    const lista = modo === 'hipotenusa' ? RETOS_HIPOTENUSA : RETOS_APLICA;
    if (!mantenerIndice) {
      idxReto = (idxReto + 1) % lista.length;
    }
    retoActual = lista[idxReto];
    anguloMarcado = false;
    hipMarcada = false;
    respondido = false;
    setObjetivoCaza('angulo');

    const fb = document.getElementById('cazador-feedback');
    fb.style.borderLeftColor = '#0284c7';
    fb.style.backgroundColor = '#f0f9ff';
    fb.style.color = '#0f172a';
    fb.textContent = modo === 'hipotenusa'
      ? `Figura: ${retoActual.nombre}. Empieza marcando el vértice del ángulo de 90°.`
      : `Figura: ${retoActual.nombre}. Decide si se aplica el Teorema de Pitágoras.`;

    dibujarFigura();
  };

  function dibujarFigura() {
    const capa = document.getElementById('capa-figura-cazador');
    capa.innerHTML = '';

    const pts = retoActual.vertices.map(v => `${v.x},${v.y}`).join(' ');
    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('points', pts);
    poly.setAttribute('fill', '#e0f2fe');
    poly.setAttribute('stroke', '#0f172a');
    poly.setAttribute('stroke-width', '3');
    poly.setAttribute('stroke-linejoin', 'round');
    capa.appendChild(poly);

    if (retoActual.diagonal) {
      const a = retoActual.vertices[retoActual.diagonal[0]];
      const b = retoActual.vertices[retoActual.diagonal[1]];
      const diag = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      diag.setAttribute('x1', a.x); diag.setAttribute('y1', a.y);
      diag.setAttribute('x2', b.x); diag.setAttribute('y2', b.y);
      diag.setAttribute('stroke', '#0284c7');
      diag.setAttribute('stroke-width', '2.5');
      diag.setAttribute('stroke-dasharray', '6,4');
      capa.appendChild(diag);
    }

    if (modo === 'hipotenusa') {
      if (anguloMarcado) {
        dibujarMarcaAnguloRecto(capa, retoActual.vertices, retoActual.idxRecto);
      }

      const n = retoActual.vertices.length;
      for (let i = 0; i < n; i++) {
        const v1 = retoActual.vertices[i];
        const v2 = retoActual.vertices[(i + 1) % n];

        if (hipMarcada && i === retoActual.hipIdx) {
          const visible = document.createElementNS('http://www.w3.org/2000/svg', 'line');
          visible.setAttribute('x1', v1.x); visible.setAttribute('y1', v1.y);
          visible.setAttribute('x2', v2.x); visible.setAttribute('y2', v2.y);
          visible.setAttribute('stroke', '#ea580c');
          visible.setAttribute('stroke-width', '6');
          visible.setAttribute('stroke-linecap', 'round');
          capa.appendChild(visible);
        }

        const seg = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        seg.setAttribute('x1', v1.x); seg.setAttribute('y1', v1.y);
        seg.setAttribute('x2', v2.x); seg.setAttribute('y2', v2.y);
        seg.setAttribute('stroke', 'transparent');
        seg.setAttribute('stroke-width', '16');
        seg.setAttribute('stroke-linecap', 'round');
        seg.style.cursor = 'pointer';
        seg.addEventListener('click', () => clicLado(i));
        capa.appendChild(seg);
      }

      retoActual.vertices.forEach((v, idx) => {
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', v.x);
        circle.setAttribute('cy', v.y);
        circle.setAttribute('r', (anguloMarcado && idx === retoActual.idxRecto) ? '12' : '9');
        circle.setAttribute('fill', (anguloMarcado && idx === retoActual.idxRecto) ? '#facc15' : '#ffffff');
        circle.setAttribute('stroke', '#0f172a');
        circle.setAttribute('stroke-width', '2.5');
        circle.style.cursor = 'pointer';
        circle.addEventListener('click', () => clicVertice(idx));
        capa.appendChild(circle);

        if (anguloMarcado && idx === retoActual.idxRecto) {
          const lbl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          lbl.setAttribute('x', v.x);
          lbl.setAttribute('y', v.y + 4);
          lbl.setAttribute('text-anchor', 'middle');
          lbl.setAttribute('font-size', '10');
          lbl.setAttribute('font-weight', '800');
          lbl.setAttribute('fill', '#0f172a');
          lbl.style.pointerEvents = 'none';
          lbl.textContent = '90°';
          capa.appendChild(lbl);
        }
      });
    } else if (respondido && retoActual.esRectangulo && retoActual.marcarRecto !== undefined) {
      dibujarMarcaAnguloRecto(capa, retoActual.vertices, retoActual.marcarRecto);
    }
  }

  function clicVertice(idx) {
    if (modo !== 'hipotenusa') return;
    const fb = document.getElementById('cazador-feedback');
    if (idx === retoActual.idxRecto) {
      anguloMarcado = true;
      setObjetivoCaza('hipotenusa');
      fb.style.borderLeftColor = '#16a34a';
      fb.style.backgroundColor = '#f0fdf4';
      fb.textContent = hipMarcada
        ? `¡Muy bien! ${retoActual.explicacion}`
        : '¡Correcto! Ese es el ángulo de 90°. Ahora haz clic sobre la hipotenusa (el lado opuesto).';
    } else {
      fb.style.borderLeftColor = '#dc2626';
      fb.style.backgroundColor = '#fef2f2';
      fb.textContent = 'Ese vértice no forma un ángulo recto de 90°. Busca la esquina que tiene forma de escuadra.';
    }
    dibujarFigura();
  }

  function clicLado(idxLado) {
    if (modo !== 'hipotenusa') return;
    const fb = document.getElementById('cazador-feedback');
    if (idxLado === retoActual.hipIdx) {
      hipMarcada = true;
      fb.style.borderLeftColor = '#16a34a';
      fb.style.backgroundColor = '#f0fdf4';
      fb.textContent = anguloMarcado
        ? `¡Excelente! Has cazado el ángulo de 90° y la hipotenusa. ${retoActual.explicacion}`
        : '¡Bien! Ese lado es la hipotenusa. No olvides marcar también el vértice de 90° en su esquina.';
    } else {
      fb.style.borderLeftColor = '#dc2626';
      fb.style.backgroundColor = '#fef2f2';
      fb.textContent = 'Ese lado es uno de los catetos (forma el ángulo de 90°). La hipotenusa es el lado opuesto y el más largo.';
    }
    dibujarFigura();
  }

  window.responderAplica = function(respuestaUsuario) {
    respondido = true;
    const fb = document.getElementById('cazador-feedback');
    if (respuestaUsuario === retoActual.esRectangulo) {
      fb.style.borderLeftColor = '#16a34a';
      fb.style.backgroundColor = '#f0fdf4';
      fb.textContent = `¡Correcto! ${retoActual.explicacion}`;
    } else {
      fb.style.borderLeftColor = '#dc2626';
      fb.style.backgroundColor = '#fef2f2';
      fb.textContent = `Revisa la figura: ${retoActual.explicacion}`;
    }
    dibujarFigura();
  };

  cambiarModoCazador('hipotenusa');
})();
</script>
