{"ideviceId":"idevice-1795277007070-wl0hvxmls","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div style="margin: 12px 0 6px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; line-height: 1.55;">
<p style="margin: 0 0 6px 0; font-size: 0.98rem;">Experimenta con las medidas de los catetos en una cuadrícula y practica el cálculo de la hipotenusa o de un cateto paso a paso.</p>
<strong>Instrucciones:</strong>
<ul>
<li style="font-size: 0.95rem; color: #334155;">
<p>En <em>Explorar en cuadrícula</em>, mueve los puntos o controles para ver cómo cambian los cuadrados y la hipotenusa.</p>
</li>
<li style="font-size: 0.95rem; color: #334155;">
<p>En <em>Reto</em>, escribe los resultados de los dos pasos y pulsa <em>Comprobar</em>.</p>
</li>
</ul>
<hr /></div>
<div id="lab-lados-pitagoras" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><!-- Selector de modo -->
<div style="display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center;"><span style="font-size: 0.88rem; font-weight: 800; color: #0f172a;">Modo de trabajo:</span>
<div role="button" onclick="cambiarModoLabLados('explorar')" id="btn-lab-explorar" style="padding: 6px 14px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #0284c7; color: #ffffff;" tabindex="0">1. Explorar en cuadrícula</div>
<div role="button" onclick="cambiarModoLabLados('reto')" id="btn-lab-reto" style="padding: 6px 14px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">2. Reto: Calcula el lado que falta</div>
</div>
<p id="lab-lados-desc" style="margin: 0 0 14px 0; font-size: 0.98rem; color: #334155; line-height: 1.5;"></p>
<!-- Contenedor principal en 2 columnas responsivas -->
<div style="display: flex; flex-wrap: wrap; gap: 18px; align-items: stretch;"><!-- Columna izquierda: Cuadrícula interactiva SVG -->
<div style="flex: 1 1 360px; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden; box-shadow: inset 0 1px 4px rgba(0,0,0,0.04);"><svg id="svg-lab-lados" viewbox="0 0 440 360" style="width: 100%; height: auto; display: block; touch-action: none;"> <defs> <pattern id="grid-lab-pit" width="22" height="22" patternunits="userSpaceOnUse"> <path d="M 22 0 L 0 0 0 22" fill="none" stroke="#e2e8f0" stroke-width="1"></path> </pattern> </defs> <rect width="440" height="360" fill="#f8fafc"></rect> <rect x="44" y="22" width="352" height="308" fill="url(#grid-lab-pit)" stroke="#cbd5e1" stroke-width="1"></rect> <g id="capa-lab-dibujo"></g> </svg></div>
<!-- Columna derecha: Controles y Cálculos -->
<div style="flex: 1 1 320px; display: flex; flex-direction: column; justify-content: space-between; gap: 12px;"><!-- Panel Modo Explorar -->
<div id="panel-explorar-lados" style="background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px;">
<div style="margin-bottom: 14px;">
<div style="display: flex; justify-content: space-between; font-weight: 800; font-size: 0.92rem; color: #0369a1; margin-bottom: 4px;"><span>Cateto vertical (a):</span> <span id="txt-val-a">3 u</span></div>
<input type="range" id="slider-a" min="1" max="12" value="3" oninput="actualizarDesdeSlider()" style="width: 100%; accent-color: #0284c7; cursor: pointer;" /></div>
<div style="margin-bottom: 16px;">
<div style="display: flex; justify-content: space-between; font-weight: 800; font-size: 0.92rem; color: #15803d; margin-bottom: 4px;"><span>Cateto horizontal (b):</span> <span id="txt-val-b">4 u</span></div>
<input type="range" id="slider-b" min="1" max="14" value="4" oninput="actualizarDesdeSlider()" style="width: 100%; accent-color: #16a34a; cursor: pointer;" /></div>
<!-- Tabla de cuadrados -->
<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; font-size: 0.94rem; line-height: 1.7;">
<div><strong style="color: #0369a1;">a²</strong> = <span id="calc-a2">9</span></div>
<div><strong style="color: #15803d;">b²</strong> = <span id="calc-b2">16</span></div>
<div style="border-top: 1px dashed #cbd5e1; margin-top: 6px; padding-top: 6px;"><strong style="color: #c2410c;">c² = a² + b²</strong> = <span id="calc-c2">25</span></div>
<div><strong style="color: #c2410c;">Hipotenusa c = √<span id="calc-raiz-in">25</span></strong> = <strong id="calc-c" style="font-size: 1.05rem;">5 u</strong></div>
</div>
<div id="aviso-terna" style="margin-top: 12px; padding: 10px 12px; border-radius: 6px; font-size: 0.9rem; font-weight: bold;"></div>
</div>
<!-- Panel Modo Reto -->
<div id="panel-reto-lados" style="display: none; background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px;">
<div id="reto-enunciado" style="font-size: 0.96rem; font-weight: bold; color: #0f172a; margin-bottom: 12px; line-height: 1.5;"></div>
<div style="display: flex; flex-direction: column; gap: 10px; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px;">
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="lbl-paso1" style="font-size: 0.9rem; font-weight: bold; color: #334155;"></label> <input type="number" id="inp-paso1" style="width: 85px; padding: 6px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="lbl-paso2" style="font-size: 0.9rem; font-weight: bold; color: #334155;"></label> <input type="number" id="inp-paso2" style="width: 85px; padding: 6px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
</div>
<div id="reto-feedback" style="margin-top: 10px; font-size: 0.9rem; font-weight: bold; min-height: 22px; line-height: 1.4;"></div>
<div style="margin-top: 12px; display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap;">
<div role="button" onclick="comprobarRetoLados()" style="background-color: #16a34a; border: 2px solid #15803d; color: #ffffff; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Comprobar</div>
<div role="button" onclick="siguienteRetoLados()" style="background-color: #ffffff; border: 2px solid #0284c7; color: #0369a1; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Otro reto →</div>
</div>
</div>
</div>
</div>
</div>
<p>
<script>
(function() {
  const PASO = 22; // 1 unidad = 22 px en la cuadrícula
  const OX = 66;   // Origen X del ángulo recto
  const OY = 308;  // Origen Y del ángulo recto

  let modo = 'explorar';
  let a = 3;
  let b = 4;
  let arrastrando = null; // 'a' o 'b'

  // Retos con ternas enteras sencillas (tipo: 'hip' busca c, tipo: 'cat' busca b)
  const RETOS = [
    { tipo: 'hip', a: 3, b: 4, c: 5 },
    { tipo: 'hip', a: 6, b: 8, c: 10 },
    { tipo: 'cat', a: 3, b: 4, c: 5 },
    { tipo: 'hip', a: 5, b: 12, c: 13 },
    { tipo: 'cat', a: 6, b: 8, c: 10 },
    { tipo: 'cat', a: 5, b: 12, c: 13 }
  ];
  let idxReto = 0;

  window.cambiarModoLabLados = function(nuevoModo) {
    modo = nuevoModo;
    const bExp = document.getElementById('btn-lab-explorar');
    const bRet = document.getElementById('btn-lab-reto');

    if (modo === 'explorar') {
      bExp.style.backgroundColor = '#0284c7';
      bExp.style.color = '#ffffff';
      bRet.style.backgroundColor = '#ffffff';
      bRet.style.color = '#0369a1';
      document.getElementById('panel-explorar-lados').style.display = 'block';
      document.getElementById('panel-reto-lados').style.display = 'none';
      document.getElementById('lab-lados-desc').innerHTML =
        'Arrastra los puntos azul y verde sobre la cuadrícula (o usa los deslizadores) para cambiar la medida de los catetos y observa cómo se calcula la hipotenusa.';
      a = parseInt(document.getElementById('slider-a').value, 10);
      b = parseInt(document.getElementById('slider-b').value, 10);
      renderLab();
    } else {
      bRet.style.backgroundColor = '#0284c7';
      bRet.style.color = '#ffffff';
      bExp.style.backgroundColor = '#ffffff';
      bExp.style.color = '#0369a1';
      document.getElementById('panel-explorar-lados').style.display = 'none';
      document.getElementById('panel-reto-lados').style.display = 'block';
      document.getElementById('lab-lados-desc').innerHTML =
        'Observa los datos del triángulo rectángulo en la cuadrícula y completa los dos pasos para hallar el lado desconocido.';
      cargarRetoActual();
    }
  };

  window.actualizarDesdeSlider = function() {
    a = parseInt(document.getElementById('slider-a').value, 10);
    b = parseInt(document.getElementById('slider-b').value, 10);
    renderLab();
  };

  function cargarRetoActual() {
    const r = RETOS[idxReto];
    a = r.a;
    b = r.b;

    document.getElementById('inp-paso1').value = '';
    document.getElementById('inp-paso2').value = '';
    document.getElementById('inp-paso1').style.borderColor = '#cbd5e1';
    document.getElementById('inp-paso2').style.borderColor = '#cbd5e1';
    document.getElementById('reto-feedback').textContent = '';

    if (r.tipo === 'hip') {
      document.getElementById('reto-enunciado').innerHTML =
        `Conocemos los dos catetos (<span style="color:#0369a1;">a = ${r.a}</span> y <span style="color:#15803d;">b = ${r.b}</span>). Halla la <span style="color:#c2410c;">hipotenusa (c)</span>:`;
      document.getElementById('lbl-paso1').textContent = `1. Suma de cuadrados (c² = ${r.a}² + ${r.b}²):`;
      document.getElementById('lbl-paso2').textContent = `2. Raíz cuadrada (c = √c²):`;
    } else {
      document.getElementById('reto-enunciado').innerHTML =
        `Conocemos la <span style="color:#c2410c;">hipotenusa (c = ${r.c})</span> y un cateto (<span style="color:#0369a1;">a = ${r.a}</span>). Halla el <span style="color:#15803d;">cateto (b)</span>:`;
      document.getElementById('lbl-paso1').textContent = `1. Resta de cuadrados (b² = ${r.c}² − ${r.a}²):`;
      document.getElementById('lbl-paso2').textContent = `2. Raíz cuadrada (b = √b²):`;
    }
    renderLab();
  }

  window.comprobarRetoLados = function() {
    const r = RETOS[idxReto];
    const v1 = parseFloat(document.getElementById('inp-paso1').value);
    const v2 = parseFloat(document.getElementById('inp-paso2').value);
    const esp1 = r.tipo === 'hip' ? (r.c * r.c) : (r.b * r.b);
    const esp2 = r.tipo === 'hip' ? r.c : r.b;

    const ok1 = v1 === esp1;
    const ok2 = v2 === esp2;

    document.getElementById('inp-paso1').style.borderColor = ok1 ? '#16a34a' : '#dc2626';
    document.getElementById('inp-paso2').style.borderColor = ok2 ? '#16a34a' : '#dc2626';

    const fb = document.getElementById('reto-feedback');
    if (ok1 && ok2) {
      fb.style.color = '#15803d';
      fb.textContent = r.tipo === 'hip'
        ? `¡Exacto! ${r.a}² + ${r.b}² = ${esp1}, y su raíz cuadrada es c = ${r.c} u.`
        : `¡Exacto! ${r.c}² − ${r.a}² = ${esp1}, y su raíz cuadrada es b = ${r.b} u.`;
    } else {
      fb.style.color = '#dc2626';
      fb.textContent = !ok1
        ? 'Revisa el paso 1: recuerda elevar primero cada lado al cuadrado.'
        : 'El paso 1 es correcto, pero revisa la raíz cuadrada del paso 2.';
    }
  };

  window.siguienteRetoLados = function() {
    idxReto = (idxReto + 1) % RETOS.length;
    cargarRetoActual();
  };

  function renderLab() {
    const capa = document.getElementById('capa-lab-dibujo');
    capa.innerHTML = '';

    const pxA = a * PASO;
    const pxB = b * PASO;
    const xA = OX;
    const yA = OY - pxA;
    const xB = OX + pxB;
    const yB = OY;

    // Triángulo relleno
    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('points', `${OX},${OY} ${xA},${yA} ${xB},${yB}`);
    poly.setAttribute('fill', '#fef08a');
    poly.setAttribute('fill-opacity', '0.6');
    capa.appendChild(poly);

    // Marca ángulo recto 90º
    const ang = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
    ang.setAttribute('points', `${OX},${OY - 14} ${OX + 14},${OY - 14} ${OX + 14},${OY}`);
    ang.setAttribute('fill', 'none');
    ang.setAttribute('stroke', '#0f172a');
    ang.setAttribute('stroke-width', '2');
    capa.appendChild(ang);

    // Cateto a (vertical azul)
    const lineaA = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    lineaA.setAttribute('x1', OX); lineaA.setAttribute('y1', OY);
    lineaA.setAttribute('x2', xA); lineaA.setAttribute('y2', yA);
    lineaA.setAttribute('stroke', '#0284c7');
    lineaA.setAttribute('stroke-width', '4');
    capa.appendChild(lineaA);

    // Cateto b (horizontal verde)
    const lineaB = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    lineaB.setAttribute('x1', OX); lineaB.setAttribute('y1', OY);
    lineaB.setAttribute('x2', xB); lineaB.setAttribute('y2', yB);
    lineaB.setAttribute('stroke', '#16a34a');
    lineaB.setAttribute('stroke-width', '4');
    capa.appendChild(lineaB);

    // Hipotenusa c (naranja)
    const lineaC = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    lineaC.setAttribute('x1', xA); lineaC.setAttribute('y1', yA);
    lineaC.setAttribute('x2', xB); lineaC.setAttribute('y2', yB);
    lineaC.setAttribute('stroke', '#ea580c');
    lineaC.setAttribute('stroke-width', '4');
    capa.appendChild(lineaC);

    // Etiquetas sobre los lados
    const c2 = a * a + b * b;
    const cVal = Math.sqrt(c2);
    const esEntero = Number.isInteger(cVal);
    const rActual = RETOS[idxReto];

    const txtA = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    txtA.setAttribute('x', OX - 10);
    txtA.setAttribute('y', OY - pxA / 2 + 4);
    txtA.setAttribute('text-anchor', 'end');
    txtA.setAttribute('font-size', '13');
    txtA.setAttribute('font-weight', '800');
    txtA.setAttribute('fill', '#0369a1');
    txtA.textContent = `a=${a}`;
    capa.appendChild(txtA);

    const txtB = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    txtB.setAttribute('x', OX + pxB / 2);
    txtB.setAttribute('y', OY + 20);
    txtB.setAttribute('text-anchor', 'middle');
    txtB.setAttribute('font-size', '13');
    txtB.setAttribute('font-weight', '800');
    txtB.setAttribute('fill', '#15803d');
    txtB.textContent = (modo === 'reto' && rActual.tipo === 'cat') ? 'b=?' : `b=${b}`;
    capa.appendChild(txtB);

    const txtC = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    txtC.setAttribute('x', (xA + xB) / 2 + 12);
    txtC.setAttribute('y', (yA + yB) / 2 - 8);
    txtC.setAttribute('font-size', '13');
    txtC.setAttribute('font-weight', '800');
    txtC.setAttribute('fill', '#c2410c');
    if (modo === 'reto') {
      txtC.textContent = rActual.tipo === 'hip' ? 'c=?' : `c=${rActual.c}`;
    } else {
      txtC.textContent = esEntero ? `c=${cVal}` : `c≈${cVal.toFixed(2)}`;
    }
    capa.appendChild(txtC);

    // Tiradores arrastrables en modo Explorar
    if (modo === 'explorar') {
      const hA = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      hA.setAttribute('cx', xA); hA.setAttribute('cy', yA); hA.setAttribute('r', '8');
      hA.setAttribute('fill', '#0284c7'); hA.setAttribute('stroke', '#ffffff'); hA.setAttribute('stroke-width', '2');
      hA.style.cursor = 'ns-resize';
      hA.addEventListener('mousedown', (e) => { e.preventDefault(); arrastrando = 'a'; });
      hA.addEventListener('touchstart', (e) => { e.preventDefault(); arrastrando = 'a'; }, { passive: false });
      capa.appendChild(hA);

      const hB = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      hB.setAttribute('cx', xB); hB.setAttribute('cy', yB); hB.setAttribute('r', '8');
      hB.setAttribute('fill', '#16a34a'); hB.setAttribute('stroke', '#ffffff'); hB.setAttribute('stroke-width', '2');
      hB.style.cursor = 'ew-resize';
      hB.addEventListener('mousedown', (e) => { e.preventDefault(); arrastrando = 'b'; });
      hB.addEventListener('touchstart', (e) => { e.preventDefault(); arrastrando = 'b'; }, { passive: false });
      capa.appendChild(hB);
    }

    // Actualizar textos del panel Explorar
    document.getElementById('txt-val-a').textContent = `${a} u`;
    document.getElementById('txt-val-b').textContent = `${b} u`;
    document.getElementById('calc-a2').textContent = `${a}² = ${a * a}`;
    document.getElementById('calc-b2').textContent = `${b}² = ${b * b}`;
    document.getElementById('calc-c2').textContent = `${a * a} + ${b * b} = ${c2}`;
    document.getElementById('calc-raiz-in').textContent = c2;
    document.getElementById('calc-c').textContent = esEntero ? `${cVal} u (¡Exacto!)` : `${cVal.toFixed(2)} u`;

    const aviso = document.getElementById('aviso-terna');
    if (esEntero) {
      aviso.style.backgroundColor = '#dcfce7';
      aviso.style.color = '#15803d';
      aviso.textContent = `¡Terna pitagórica exacta! (${a}, ${b}, ${cVal}) forman tres lados enteros.`;
    } else {
      aviso.style.backgroundColor = '#f0f9ff';
      aviso.style.color = '#0369a1';
      aviso.textContent = `Prueba a buscar combinaciones donde c sea un número entero exacto (ej. 3 y 4, o 6 y 8).`;
    }
  }

  function moverPunto(e) {
    if (!arrastrando || modo !== 'explorar') return;
    e.preventDefault();
    const svg = document.getElementById('svg-lab-lados');
    const pt = svg.createSVGPoint();
    if (e.touches && e.touches.length > 0) {
      pt.x = e.touches[0].clientX;
      pt.y = e.touches[0].clientY;
    } else {
      pt.x = e.clientX;
      pt.y = e.clientY;
    }
    const p = pt.matrixTransform(svg.getScreenCTM().inverse());

    if (arrastrando === 'a') {
      const nuevoA = Math.round((OY - p.y) / PASO);
      a = Math.max(1, Math.min(12, nuevoA));
      document.getElementById('slider-a').value = a;
    } else if (arrastrando === 'b') {
      const nuevoB = Math.round((p.x - OX) / PASO);
      b = Math.max(1, Math.min(14, nuevoB));
      document.getElementById('slider-b').value = b;
    }
    renderLab();
  }

  function soltarPunto() {
    arrastrando = null;
  }

  const svg = document.getElementById('svg-lab-lados');
  svg.addEventListener('mousemove', moverPunto);
  svg.addEventListener('mouseup', soltarPunto);
  svg.addEventListener('mouseleave', soltarPunto);
  svg.addEventListener('touchmove', moverPunto, { passive: false });
  svg.addEventListener('touchend', soltarPunto);

  cambiarModoLabLados('explorar');
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1795277238471-ji4xudba0","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div style="margin: 12px 0 6px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; line-height: 1.55;">
<p style="margin: 0 0 6px 0; font-size: 0.98rem;">Comprueba de forma manipulativa qué tres longitudes permiten cerrar un triángulo y cuáles forman un ángulo recto de 90°.</p>
<p style="margin: 0; font-size: 0.95rem; color: #334155;"><strong>Instrucciones:</strong> Selecciona un grupo de reglas, <strong>abre o cierra el ángulo</strong> con el deslizador para ver si el triángulo cierra y comprueba qué sucede al situarlo en <strong>90°</strong>.</p>
</div>
<div id="reglas-triangulo-pit" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><hr /><!-- Conjuntos predefinidos de reglas -->
<div style="display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center;"><span style="font-size: 0.88rem; font-weight: 800; color: #0f172a;">Reglas propuestas:</span>
<div role="button" onclick="cargarReglas(0)" id="btn-reg-0" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #0284c7; color: #ffffff;" tabindex="0">3, 4 y 5</div>
<div role="button" onclick="cargarReglas(1)" id="btn-reg-1" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">2, 3 y 6</div>
<div role="button" onclick="cargarReglas(2)" id="btn-reg-2" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">3, 4 y 6</div>
<div role="button" onclick="cargarReglas(3)" id="btn-reg-3" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">6, 8 y 10</div>
</div>
<!-- Escena SVG -->
<div style="width: 100%; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden; box-shadow: inset 0 1px 4px rgba(0,0,0,0.04);"><svg id="svg-reglas-tri" viewbox="0 0 760 360" style="width: 100%; height: auto; display: block;"> <rect width="760" height="360" fill="#f8fafc"></rect> <g id="capa-reglas-dibujo"></g> </svg></div>
<!-- Control de apertura del ángulo para probar si cierra y si es de 90º -->
<div id="panel-apertura-reglas" style="margin-top: 12px; background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 12px 16px;">
<div style="display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 6px;"><span style="font-size: 0.92rem; font-weight: 800; color: #0f172a;"> Abre o cierra el ángulo entre las dos primeras reglas: <span id="txt-angulo-reglas" style="color: #0284c7;">55°</span> </span>
<div role="button" onclick="ajustarAngulo90()" style="background-color: #fef08a; border: 2px solid #0f172a; color: #0f172a; font-weight: 800; font-size: 0.82rem; padding: 5px 12px; border-radius: 6px; cursor: pointer;" tabindex="0">Colocar en 90°</div>
</div>
<input type="range" id="slider-angulo-reg" min="20" max="150" value="55" oninput="actualizarAnguloSlider()" style="width: 100%; accent-color: #0284c7; cursor: pointer;" /></div>
<!-- Diagnóstico pedagógico -->
<div id="diagnostico-reglas" style="margin-top: 14px; background-color: #f0f9ff; border-left: 5px solid #0284c7; border-radius: 6px; padding: 14px 16px; font-size: 0.95rem; font-weight: bold; color: #0f172a; line-height: 1.55;"></div>
</div>
<p>
<script>
(function() {
  // anguloInicial distinto de 90° para que el alumno manipule hasta encontrar el cierre / 90°
  const CONJUNTOS = [
    { l1: 3, l2: 4, l3: 5, anguloInicial: 55 },
    { l1: 2, l2: 3, l3: 6, anguloInicial: 115 },
    { l1: 3, l2: 4, l3: 6, anguloInicial: 50 },
    { l1: 6, l2: 8, l3: 10, anguloInicial: 125 }
  ];

  const ESCALA = 26;
  const OX = 210;
  const OY = 265;

  let idxActual = 0;
  let anguloDeg = 55;

  window.cargarReglas = function(idx) {
    idxActual = idx;
    for (let i = 0; i < CONJUNTOS.length; i++) {
      const btn = document.getElementById('btn-reg-' + i);
      if (i === idx) {
        btn.style.backgroundColor = '#0284c7';
        btn.style.color = '#ffffff';
      } else {
        btn.style.backgroundColor = '#ffffff';
        btn.style.color = '#0369a1';
      }
    }
    anguloDeg = CONJUNTOS[idx].anguloInicial;
    document.getElementById('slider-angulo-reg').value = anguloDeg;
    renderReglas();
  };

  window.actualizarAnguloSlider = function() {
    anguloDeg = parseInt(document.getElementById('slider-angulo-reg').value, 10);
    renderReglas();
  };

  window.ajustarAngulo90 = function() {
    anguloDeg = 90;
    document.getElementById('slider-angulo-reg').value = 90;
    renderReglas();
  };

  function renderReglas() {
    const { l1, l2, l3 } = CONJUNTOS[idxActual];
    document.getElementById('txt-angulo-reglas').textContent = `${anguloDeg}°`;

    const capa = document.getElementById('capa-reglas-dibujo');
    capa.innerHTML = '';

    const p0 = { x: OX, y: OY };
    const p1 = { x: OX + l1 * ESCALA, y: OY };

    const rad = -anguloDeg * Math.PI / 180;
    const p2 = {
      x: OX + l2 * ESCALA * Math.cos(rad),
      y: OY + l2 * ESCALA * Math.sin(rad)
    };

    const distActual = Math.hypot(p1.x - p2.x, p1.y - p2.y) / ESCALA;
    const cierreExitoso = Math.abs(distActual - l3) < 0.08;

    if (cierreExitoso) {
      const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
      poly.setAttribute('points', `${p0.x},${p0.y} ${p1.x},${p1.y} ${p2.x},${p2.y}`);
      poly.setAttribute('fill', anguloDeg === 90 ? '#dcfce7' : '#fef9c3');
      poly.setAttribute('opacity', '0.75');
      capa.appendChild(poly);
    }

    const r1 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    r1.setAttribute('x1', p0.x); r1.setAttribute('y1', p0.y);
    r1.setAttribute('x2', p1.x); r1.setAttribute('y2', p1.y);
    r1.setAttribute('stroke', '#0284c7'); r1.setAttribute('stroke-width', '5'); r1.setAttribute('stroke-linecap', 'round');
    capa.appendChild(r1);

    const r2 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    r2.setAttribute('x1', p0.x); r2.setAttribute('y1', p0.y);
    r2.setAttribute('x2', p2.x); r2.setAttribute('y2', p2.y);
    r2.setAttribute('stroke', '#16a34a'); r2.setAttribute('stroke-width', '5'); r2.setAttribute('stroke-linecap', 'round');
    capa.appendChild(r2);

    const r3 = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    r3.setAttribute('x1', p1.x); r3.setAttribute('y1', p1.y);
    if (cierreExitoso) {
      r3.setAttribute('x2', p2.x); r3.setAttribute('y2', p2.y);
      r3.setAttribute('stroke', '#ea580c'); r3.setAttribute('stroke-width', '5');
    } else {
      const angHaciaP2 = Math.atan2(p2.y - p1.y, p2.x - p1.x);
      const extX = p1.x + l3 * ESCALA * Math.cos(angHaciaP2);
      const extY = p1.y + l3 * ESCALA * Math.sin(angHaciaP2);
      r3.setAttribute('x2', extX); r3.setAttribute('y2', extY);
      r3.setAttribute('stroke', '#ea580c'); r3.setAttribute('stroke-width', '4'); r3.setAttribute('stroke-dasharray', '6,4');
    }
    r3.setAttribute('stroke-linecap', 'round');
    capa.appendChild(r3);

    if (anguloDeg === 90) {
      const esc = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
      esc.setAttribute('points', `${OX},${OY - 14} ${OX + 14},${OY - 14} ${OX + 14},${OY}`);
      esc.setAttribute('fill', 'none'); esc.setAttribute('stroke', '#0f172a'); esc.setAttribute('stroke-width', '2');
      capa.appendChild(esc);
    }

    const t1 = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t1.setAttribute('x', (p0.x + p1.x) / 2); t1.setAttribute('y', OY + 22);
    t1.setAttribute('text-anchor', 'middle'); t1.setAttribute('font-size', '13'); t1.setAttribute('font-weight', '800'); t1.setAttribute('fill', '#0369a1');
    t1.textContent = `Regla ${l1}`;
    capa.appendChild(t1);

    const t2 = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t2.setAttribute('x', (p0.x + p2.x) / 2 - 14); t2.setAttribute('y', (p0.y + p2.y) / 2);
    t2.setAttribute('text-anchor', 'end'); t2.setAttribute('font-size', '13'); t2.setAttribute('font-weight', '800'); t2.setAttribute('fill', '#15803d');
    t2.textContent = `Regla ${l2}`;
    capa.appendChild(t2);

    const t3 = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t3.setAttribute('x', (p1.x + p2.x) / 2 + 16); t3.setAttribute('y', (p1.y + p2.y) / 2 - 8);
    t3.setAttribute('font-size', '13'); t3.setAttribute('font-weight', '800'); t3.setAttribute('fill', '#c2410c');
    t3.textContent = `Regla ${l3}`;
    capa.appendChild(t3);

    const diag = document.getElementById('diagnostico-reglas');
    const ladosOrdenados = [l1, l2, l3].sort((x, y) => x - y);
    const [x, y, z] = ladosOrdenados;
    const esTrianguloPosible = (x + y) > z;
    const cumplePitagoras = (x * x + y * y) === (z * z);

    if (!esTrianguloPosible) {
      diag.style.borderLeftColor = '#dc2626';
      diag.style.backgroundColor = '#fef2f2';
      diag.innerHTML = `No se puede formar ningún triángulo con <strong>${l1}, ${l2} y ${l3}</strong>: la suma de los dos lados más cortos (${x} + ${y} = ${x + y}) es menor que el lado mayor (${z}).`;
    } else if (cierreExitoso && anguloDeg === 90 && cumplePitagoras) {
      diag.style.borderLeftColor = '#16a34a';
      diag.style.backgroundColor = '#f0fdf4';
      diag.innerHTML = `¡Encaja a 90°! Las reglas <strong>${l1}, ${l2} y ${l3}</strong> forman un <strong>triángulo rectángulo</strong> y cumplen Pitágoras: ${x}² + ${y}² = ${x*x} + ${y*y} = ${z*z} = ${z}².`;
    } else if (cierreExitoso && cumplePitagoras) {
      diag.style.borderLeftColor = '#d97706';
      diag.style.backgroundColor = '#fffbeb';
      diag.innerHTML = `¡El triángulo cierra con <strong>${l1}, ${l2} y ${l3}</strong>!, pero a ${anguloDeg}° aún no es rectángulo. Mueve el deslizador hasta <strong>90°</strong> para comprobarlo.`;
    } else if (cierreExitoso && !cumplePitagoras) {
      diag.style.borderLeftColor = '#0284c7';
      diag.style.backgroundColor = '#f0f9ff';
      diag.innerHTML = `Con <strong>${l1}, ${l2} y ${l3}</strong> se cierra un triángulo (${x} + ${y} > ${z}), pero <strong>no es rectángulo</strong> (${x}² + ${y}² = ${x*x + y*y}, distinto de ${z}² = ${z*z}).`;
    } else {
      diag.style.borderLeftColor = '#64748b';
      diag.style.backgroundColor = '#f8fafc';
      diag.innerHTML = `A este ángulo (${anguloDeg}°), la distancia entre extremos es <strong>${distActual.toFixed(1)}</strong>; mueve el ángulo para ver si la regla de longitud <strong>${l3}</strong> logra cerrar el triángulo.`;
    }
  }

  cargarReglas(0);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1795277587658-qjjl6dyh2","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div style="margin: 12px 0 6px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; line-height: 1.55;">
<p style="margin: 0 0 6px 0; font-size: 0.98rem;">Aplica lo aprendido a situaciones cotidianas donde aparece oculto un triángulo rectángulo.</p>
<p style="margin: 0; font-size: 0.95rem; color: #334155;"><strong>Instrucciones:</strong> Lee el problema, rellena los dos pasos de cálculo y pulsa <em>Comprobar</em>. Si lo necesitas, usa el botón <em>Resaltar triángulo (90°)</em> para ver mejor la figura.</p>
<hr /></div>
<div id="situaciones-pitagoras-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><!-- Selector de situación cotidiana -->
<div style="display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center;"><span style="font-size: 0.88rem; font-weight: 800; color: #0f172a;">Elige una situación:</span>
<div role="button" onclick="cargarSituacionPit(0)" id="btn-sit-0" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #0284c7; color: #ffffff;" tabindex="0">1. Escalera en la pared</div>
<div role="button" onclick="cargarSituacionPit(1)" id="btn-sit-1" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">2. Rampa de acceso</div>
<div role="button" onclick="cargarSituacionPit(2)" id="btn-sit-2" style="padding: 6px 12px; border-radius: 6px; font-size: 0.88rem; font-weight: bold; cursor: pointer; border: 2px solid #0284c7; background-color: #ffffff; color: #0369a1;" tabindex="0">3. Diagonal de un campo</div>
</div>
<!-- Contenedor en dos columnas -->
<div style="display: flex; flex-wrap: wrap; gap: 18px; align-items: stretch;"><!-- Columna izquierda: Escena SVG -->
<div style="flex: 1 1 350px; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden; box-shadow: inset 0 1px 4px rgba(0,0,0,0.04);"><svg id="svg-situaciones-pit" viewbox="0 0 440 310" style="width: 100%; height: auto; display: block;"> <rect width="440" height="310" fill="#f8fafc"></rect> <g id="capa-sit-escena"></g> </svg>
<div style="padding: 8px 12px; background: #f8fafc; border-top: 1px solid #e2e8f0; display: flex; justify-content: space-between; align-items: center; gap: 8px;"><span style="font-size: 0.84rem; font-weight: bold; color: #475569;">¿No ves claro el triángulo?</span>
<div role="button" onclick="togglePistaTriangulo()" id="btn-pista-tri" style="background-color: #fef08a; border: 1.5px solid #0f172a; color: #0f172a; font-weight: 800; font-size: 0.8rem; padding: 4px 10px; border-radius: 5px; cursor: pointer;" tabindex="0">Resaltar triángulo (90°)</div>
</div>
</div>
<!-- Columna derecha: Enunciado y cálculo guiado -->
<div style="flex: 1 1 320px; background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px; display: flex; flex-direction: column; justify-content: space-between; gap: 12px;">
<div>
<div id="sit-titulo" style="font-size: 1.05rem; font-weight: 800; color: #0369a1; margin-bottom: 6px;"></div>
<p id="sit-enunciado" style="margin: 0 0 14px 0; font-size: 0.95rem; color: #334155; line-height: 1.5;"></p>
<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 10px;">
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="sit-lbl-1" style="font-size: 0.88rem; font-weight: bold; color: #334155;"></label> <input type="number" id="sit-inp-1" style="width: 82px; padding: 5px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="sit-lbl-2" style="font-size: 0.88rem; font-weight: bold; color: #334155;"></label> <input type="number" id="sit-inp-2" style="width: 82px; padding: 5px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
</div>
<div id="sit-feedback" style="margin-top: 10px; font-size: 0.9rem; font-weight: bold; min-height: 22px; line-height: 1.4;"></div>
</div>
<div style="display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap;">
<div role="button" onclick="comprobarSituacionPit()" style="background-color: #16a34a; border: 2px solid #15803d; color: #ffffff; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Comprobar</div>
<div role="button" onclick="siguienteSituacionPit()" style="background-color: #ffffff; border: 2px solid #0284c7; color: #0369a1; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Siguiente →</div>
</div>
</div>
</div>
</div>
<p>
<script>
(function() {
  const SITUACIONES = [
    {
      tipo: 'escalera',
      titulo: 'Escalera apoyada en la pared',
      enunciado: 'Una escalera mide 5 m y se apoya en una pared vertical. Su base está a 3 m de la pared. ¿A qué altura de la pared llega la parte superior de la escalera?',
      catA: 4, // altura (incógnita)
      catB: 3, // suelo
      hipC: 5, // escalera
      unidad: 'm',
      lbl1: '1. Resta de cuadrados (a² = 5² − 3²):',
      lbl2: '2. Altura (a = √a²):',
      esp1: 16,
      esp2: 4,
      explicacion: 'La escalera es la hipotenusa (5 m) y la distancia a la pared es un cateto (3 m). 5² − 3² = 25 − 9 = 16, y √16 = 4 m.'
    },
    {
      tipo: 'rampa',
      titulo: 'Rampa de acceso',
      enunciado: 'Para salvar un desnivel de 6 m de altura, se construye una rampa cuya base horizontal mide 8 m. ¿Cuál es la longitud de la rampa?',
      catA: 6, // altura
      catB: 8, // base horizontal
      hipC: 10, // rampa (incógnita)
      unidad: 'm',
      lbl1: '1. Suma de cuadrados (c² = 6² + 8²):',
      lbl2: '2. Longitud rampa (c = √c²):',
      esp1: 100,
      esp2: 10,
      explicacion: 'La altura (6 m) y la base (8 m) son los catetos; la rampa es la hipotenusa. 6² + 8² = 36 + 64 = 100, y √100 = 10 m.'
    },
    {
      tipo: 'campo',
      titulo: 'Diagonal de un campo rectangular',
      enunciado: 'Un campo rectangular tiene 12 m de largo y 5 m de ancho. ¿Cuánto mide su diagonal de esquina a esquina?',
      catA: 5, // ancho
      catB: 12, // largo
      hipC: 13, // diagonal (incógnita)
      unidad: 'm',
      lbl1: '1. Suma de cuadrados (c² = 5² + 12²):',
      lbl2: '2. Diagonal (c = √c²):',
      esp1: 169,
      esp2: 13,
      explicacion: 'Los lados del rectángulo (5 m y 12 m) forman 90° y son los catetos; la diagonal es la hipotenusa. 5² + 12² = 25 + 144 = 169, y √169 = 13 m.'
    }
  ];

  let idxActual = 0;
  let mostrarPista = false;

  window.cargarSituacionPit = function(idx) {
    idxActual = idx;
    mostrarPista = false;
    document.getElementById('btn-pista-tri').textContent = 'Resaltar triángulo (90°)';

    for (let i = 0; i < SITUACIONES.length; i++) {
      const btn = document.getElementById('btn-sit-' + i);
      if (i === idx) {
        btn.style.backgroundColor = '#0284c7';
        btn.style.color = '#ffffff';
      } else {
        btn.style.backgroundColor = '#ffffff';
        btn.style.color = '#0369a1';
      }
    }

    const s = SITUACIONES[idx];
    document.getElementById('sit-titulo').textContent = s.titulo;
    document.getElementById('sit-enunciado').textContent = s.enunciado;
    document.getElementById('sit-lbl-1').textContent = s.lbl1;
    document.getElementById('sit-lbl-2').textContent = s.lbl2;
    document.getElementById('sit-inp-1').value = '';
    document.getElementById('sit-inp-2').value = '';
    document.getElementById('sit-inp-1').style.borderColor = '#cbd5e1';
    document.getElementById('sit-inp-2').style.borderColor = '#cbd5e1';
    document.getElementById('sit-feedback').textContent = '';

    dibujarEscenaSituacion();
  };

  window.togglePistaTriangulo = function() {
    mostrarPista = !mostrarPista;
    document.getElementById('btn-pista-tri').textContent = mostrarPista
      ? 'Ocultar resaltado'
      : 'Resaltar triángulo (90°)';
    dibujarEscenaSituacion();
  };

  function dibujarEscenaSituacion() {
    const s = SITUACIONES[idxActual];
    const capa = document.getElementById('capa-sit-escena');
    capa.innerHTML = '';

    // Suelo base
    const suelo = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    suelo.setAttribute('x1', '30'); suelo.setAttribute('y1', '255');
    suelo.setAttribute('x2', '410'); suelo.setAttribute('y2', '255');
    suelo.setAttribute('stroke', '#64748b'); suelo.setAttribute('stroke-width', '3');
    capa.appendChild(suelo);

    if (s.tipo === 'escalera') {
      // Pared vertical a la derecha (x = 300)
      const pared = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      pared.setAttribute('x', '300'); pared.setAttribute('y', '45');
      pared.setAttribute('width', '14'); pared.setAttribute('height', '210');
      pared.setAttribute('fill', '#cbd5e1'); pared.setAttribute('stroke', '#475569'); pared.setAttribute('stroke-width', '1.5');
      capa.appendChild(pared);

      // Escalera desde (150, 255) hasta (300, 95)
      const esc = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      esc.setAttribute('x1', '150'); esc.setAttribute('y1', '255');
      esc.setAttribute('x2', '300'); esc.setAttribute('y2', '95');
      esc.setAttribute('stroke', '#ea580c'); esc.setAttribute('stroke-width', '5');
      capa.appendChild(esc);

      if (mostrarPista) {
        const tri = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
        tri.setAttribute('points', '150,255 300,255 300,95');
        tri.setAttribute('fill', '#fef08a'); tri.setAttribute('fill-opacity', '0.55');
        tri.setAttribute('stroke', '#0f172a'); tri.setAttribute('stroke-width', '2');
        capa.insertBefore(tri, esc);

        const ang = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
        ang.setAttribute('points', '286,255 286,241 300,241');
        ang.setAttribute('fill', 'none'); ang.setAttribute('stroke', '#0f172a'); ang.setAttribute('stroke-width', '2');
        capa.appendChild(ang);
      }

      // Etiquetas
      addLabel(capa, 225, 276, `Base = ${s.catB} ${s.unidad}`, '#15803d');
      addLabel(capa, 322, 178, `Altura = ?`, '#0369a1');
      addLabel(capa, 205, 165, `Escalera = ${s.hipC} ${s.unidad}`, '#c2410c');

    } else if (s.tipo === 'rampa') {
      // Plataforma elevada a la derecha (x = 310, y = 115)
      const plat = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      plat.setAttribute('x', '310'); plat.setAttribute('y', '115');
      plat.setAttribute('width', '90'); plat.setAttribute('height', '140');
      plat.setAttribute('fill', '#e2e8f0'); plat.setAttribute('stroke', '#475569'); plat.setAttribute('stroke-width', '1.5');
      capa.appendChild(plat);

      // Rampa desde (90, 255) hasta (310, 115)
      const rampa = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      rampa.setAttribute('x1', '90'); rampa.setAttribute('y1', '255');
      rampa.setAttribute('x2', '310'); rampa.setAttribute('y2', '115');
      rampa.setAttribute('stroke', '#ea580c'); rampa.setAttribute('stroke-width', '5');
      capa.appendChild(rampa);

      if (mostrarPista) {
        const tri = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
        tri.setAttribute('points', '90,255 310,255 310,115');
        tri.setAttribute('fill', '#fef08a'); tri.setAttribute('fill-opacity', '0.55');
        tri.setAttribute('stroke', '#0f172a'); tri.setAttribute('stroke-width', '2');
        capa.insertBefore(tri, rampa);

        const ang = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
        ang.setAttribute('points', '296,255 296,241 310,241');
        ang.setAttribute('fill', 'none'); ang.setAttribute('stroke', '#0f172a'); ang.setAttribute('stroke-width', '2');
        capa.appendChild(ang);
      }

      addLabel(capa, 200, 276, `Base = ${s.catB} ${s.unidad}`, '#15803d');
      addLabel(capa, 322, 188, `Alto = ${s.catA} ${s.unidad}`, '#0369a1');
      addLabel(capa, 175, 172, `Rampa = ?`, '#c2410c');

    } else {
      // Campo rectangular desde (95, 95) a (345, 245)
      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', '95'); rect.setAttribute('y', '95');
      rect.setAttribute('width', '250'); rect.setAttribute('height', '150');
      rect.setAttribute('fill', '#dcfce7'); rect.setAttribute('fill-opacity', '0.5');
      rect.setAttribute('stroke', '#15803d'); rect.setAttribute('stroke-width', '2.5');
      capa.appendChild(rect);

      // Diagonal
      const diag = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      diag.setAttribute('x1', '95'); diag.setAttribute('y1', '245');
      diag.setAttribute('x2', '345'); diag.setAttribute('y2', '95');
      diag.setAttribute('stroke', '#ea580c'); diag.setAttribute('stroke-width', '3.5');
      capa.appendChild(diag);

      if (mostrarPista) {
        const tri = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
        tri.setAttribute('points', '95,245 345,245 345,95');
        tri.setAttribute('fill', '#fef08a'); tri.setAttribute('fill-opacity', '0.65');
        capa.insertBefore(tri, diag);

        const ang = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
        ang.setAttribute('points', '331,245 331,231 345,231');
        ang.setAttribute('fill', 'none'); ang.setAttribute('stroke', '#0f172a'); ang.setAttribute('stroke-width', '2');
        capa.appendChild(ang);
      }

      addLabel(capa, 220, 268, `Largo = ${s.catB} ${s.unidad}`, '#15803d');
      addLabel(capa, 382, 174, `Ancho = ${s.catA} ${s.unidad}`, '#0369a1');
      addLabel(capa, 195, 160, `Diagonal = ?`, '#c2410c');
    }
  }

  function addLabel(capa, x, y, text, color) {
    const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t.setAttribute('x', x);
    t.setAttribute('y', y);
    t.setAttribute('text-anchor', 'middle');
    t.setAttribute('font-size', '12.5');
    t.setAttribute('font-weight', '800');
    t.setAttribute('fill', color);
    t.textContent = text;
    capa.appendChild(t);
  }

  window.comprobarSituacionPit = function() {
    const s = SITUACIONES[idxActual];
    const v1 = parseFloat(document.getElementById('sit-inp-1').value);
    const v2 = parseFloat(document.getElementById('sit-inp-2').value);

    const ok1 = v1 === s.esp1;
    const ok2 = v2 === s.esp2;

    document.getElementById('sit-inp-1').style.borderColor = ok1 ? '#16a34a' : '#dc2626';
    document.getElementById('sit-inp-2').style.borderColor = ok2 ? '#16a34a' : '#dc2626';

    const fb = document.getElementById('sit-feedback');
    if (ok1 && ok2) {
      fb.style.color = '#15803d';
      fb.textContent = `¡Muy bien! ${s.explicacion}`;
    } else {
      fb.style.color = '#dc2626';
      fb.textContent = !ok1
        ? 'Revisa el primer paso: fíjate bien en cuál es la hipotenusa (el lado más largo) y cuáles los catetos.'
        : 'El primer paso está bien; revisa la raíz cuadrada del segundo paso.';
    }
  };

  window.siguienteSituacionPit = function() {
    cargarSituacionPit((idxActual + 1) % SITUACIONES.length);
  };

  cargarSituacionPit(0);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1795278514842-dxgrrounr","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div style="margin: 12px 0 6px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; line-height: 1.55;">
<p style="margin: 0 0 6px 0; font-size: 0.98rem;">Practica el cálculo de perímetros y áreas en las principales figuras planas.</p>
<p style="margin: 0; font-size: 0.95rem; color: #334155;"><strong>Instrucciones:</strong> Resuelve cada reto fijándote en las medidas junto al dibujo y pulsando <em>Comprobar</em> (puedes pulsar <em>Ver fórmula</em> como ayuda).</p>
<hr /></div>
<div id="reto-areas-perimetros-app" style="margin: 10px 0; width: 100%; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><!-- Selector de figura para el reto -->
<div style="display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 14px; align-items: center;"><span style="font-size: 0.88rem; font-weight: 800; color: #0f172a;">Elige figura del reto:</span>
<div role="button" onclick="cargarRetoAreaPer(0)" id="rbtn-0" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #0284c7; color: #ffffff;" tabindex="0">Cuadrado</div>
<div role="button" onclick="cargarRetoAreaPer(1)" id="rbtn-1" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #ffffff; color: #0369a1;" tabindex="0">Rectángulo</div>
<div role="button" onclick="cargarRetoAreaPer(2)" id="rbtn-2" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #ffffff; color: #0369a1;" tabindex="0">Triángulo</div>
<div role="button" onclick="cargarRetoAreaPer(3)" id="rbtn-3" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #ffffff; color: #0369a1;" tabindex="0">Romboide</div>
<div role="button" onclick="cargarRetoAreaPer(4)" id="rbtn-4" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #ffffff; color: #0369a1;" tabindex="0">Rombo</div>
<div role="button" onclick="cargarRetoAreaPer(5)" id="rbtn-5" style="padding: 5px 11px; border-radius: 6px; font-size: 0.84rem; font-weight: bold; cursor: pointer; border: 1.5px solid #0284c7; background: #ffffff; color: #0369a1;" tabindex="0">Polígono regular</div>
</div>
<!-- Contenedor en dos columnas -->
<div style="display: flex; flex-wrap: wrap; gap: 18px; align-items: stretch;"><!-- Izquierda: Dibujo con etiquetas situadas junto a cada línea y del mismo color -->
<div style="flex: 1 1 300px; background: #ffffff; border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden;"><svg id="svg-reto-ap" viewbox="0 0 360 250" style="width: 100%; height: auto; display: block;"> <rect width="360" height="250" fill="#f8fafc"></rect> <g id="capa-reto-ap"></g> </svg></div>
<!-- Derecha: Comprobación paso a paso -->
<div style="flex: 1 1 320px; background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px; display: flex; flex-direction: column; justify-content: space-between; gap: 12px;">
<div>
<div style="display: flex; justify-content: space-between; align-items: center; gap: 8px; margin-bottom: 8px; flex-wrap: wrap;">
<div id="rap-titulo" style="font-size: 1.05rem; font-weight: 800; color: #0369a1;"></div>
<div role="button" onclick="togglePistaFormula()" id="btn-pista-formula" style="background-color: #fef08a; border: 1.5px solid #0f172a; color: #0f172a; font-weight: 800; font-size: 0.78rem; padding: 4px 10px; border-radius: 5px; cursor: pointer;" tabindex="0">Ver fórmula</div>
</div>
<!-- Fichas de medidas -->
<div id="rap-datos" style="font-size: 0.92rem; font-weight: bold; color: #334155; margin-bottom: 10px; display: flex; flex-wrap: wrap; gap: 6px;"></div>
<!-- Caja de pista con fórmulas -->
<div id="rap-pista-box" style="display: none; background: #fffbeb; border: 1px solid #f59e0b; border-radius: 6px; padding: 10px 12px; margin-bottom: 12px; font-size: 0.88rem; color: #78350f; line-height: 1.5;"></div>
<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 6px; padding: 12px; display: flex; flex-direction: column; gap: 10px;">
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="rap-lbl-per" style="font-size: 0.88rem; font-weight: bold; color: #0f172a;"></label> <input type="number" id="rap-inp-per" style="width: 84px; padding: 5px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
<div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;"><label id="rap-lbl-area" style="font-size: 0.88rem; font-weight: bold; color: #0f172a;"></label> <input type="number" step="any" id="rap-inp-area" style="width: 84px; padding: 5px; border: 2px solid #cbd5e1; border-radius: 5px; font-weight: 800; text-align: center; font-size: 0.95rem;" /></div>
</div>
<div id="rap-feedback" style="margin-top: 10px; font-size: 0.9rem; font-weight: bold; min-height: 22px; line-height: 1.45;"></div>
</div>
<div style="display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap;">
<div role="button" onclick="comprobarRetoAP()" style="background-color: #16a34a; border: 2px solid #15803d; color: #ffffff; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Comprobar</div>
<div role="button" onclick="siguienteRetoAP()" style="background-color: #ffffff; border: 2px solid #0284c7; color: #0369a1; font-weight: 800; font-size: 0.85rem; padding: 7px 14px; border-radius: 6px; cursor: pointer; text-transform: uppercase;" tabindex="0">Siguiente →</div>
</div>
</div>
</div>
</div>
<p>
<script>
(function() {
  const RETOS_AP = [
    {
      nombre: 'Reto 1: Cuadrado',
      medidas: ['Lado l = 7 cm'],
      pista: '<strong>Pista:</strong> En un cuadrado los 4 lados miden igual. Perímetro = 4 · l &nbsp;|&nbsp; Área = l².',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 28,
      area: 49,
      explicacion: 'Perímetro = 4 · 7 = 28 cm. Área = 7² = 49 cm².'
    },
    {
      nombre: 'Reto 2: Rectángulo',
      medidas: ['Base b = 9 cm', 'Altura h = 4 cm'],
      pista: '<strong>Pista:</strong> Lados iguales dos a dos. Perímetro = 2 · (b + h) &nbsp;|&nbsp; Área = b · h.',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 26,
      area: 36,
      explicacion: 'Perímetro = 2 · (9 + 4) = 26 cm. Área = 9 · 4 = 36 cm².'
    },
    {
      nombre: 'Reto 3: Triángulo',
      medidas: ['Lados: 6 cm, 8 cm y 10 cm', 'Base b = 8 cm', 'Altura h = 6 cm'],
      pista: '<strong>Pista:</strong> Perímetro = suma de los 3 lados &nbsp;|&nbsp; Área = (b · h) / 2.',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 24,
      area: 24,
      explicacion: 'Perímetro = 6 + 8 + 10 = 24 cm. Área = (8 · 6) / 2 = 24 cm².'
    },
    {
      nombre: 'Reto 4: Romboide',
      medidas: ['Base b = 10 cm', 'Lado l = 5 cm', 'Altura h = 4 cm'],
      pista: '<strong>Pista:</strong> Lados opuestos iguales. Perímetro = 2 · (b + l) &nbsp;|&nbsp; Área = b · h.',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 30,
      area: 40,
      explicacion: 'Perímetro = 2 · (10 + 5) = 30 cm. Área = 10 · 4 = 40 cm².'
    },
    {
      nombre: 'Reto 5: Rombo',
      medidas: ['Diagonal mayor D = 10 cm', 'Diagonal menor d = 6 cm', 'Lado l = 5 cm'],
      pista: '<strong>Pista:</strong> Los 4 lados son iguales. Perímetro = 4 · l &nbsp;|&nbsp; Área = (D · d) / 2.',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 20,
      area: 30,
      explicacion: 'Perímetro = 4 · 5 = 20 cm. Área = (10 · 6) / 2 = 30 cm².'
    },
    {
      nombre: 'Reto 6: Hexágono regular',
      medidas: ['6 lados iguales de l = 4 cm', 'Apotema ap = 3,5 cm'],
      pista: '<strong>Pista:</strong> Perímetro = 6 · l &nbsp;|&nbsp; Área = (Perímetro · ap) / 2.',
      lblPer: 'Perímetro (cm):',
      lblArea: 'Área (cm²):',
      per: 24,
      area: 42,
      explicacion: 'Perímetro = 6 · 4 = 24 cm. Área = (24 · 3,5) / 2 = 42 cm².'
    }
  ];

  let idxAP = 0;
  let pistaVisible = false;

  window.cargarRetoAreaPer = function(idx) {
    idxAP = idx;
    pistaVisible = false;
    document.getElementById('rap-pista-box').style.display = 'none';
    document.getElementById('btn-pista-formula').textContent = 'Ver fórmula';

    for (let i = 0; i < RETOS_AP.length; i++) {
      const b = document.getElementById('rbtn-' + i);
      if (i === idx) {
        b.style.backgroundColor = '#0284c7'; b.style.color = '#ffffff';
      } else {
        b.style.backgroundColor = '#ffffff'; b.style.color = '#0369a1';
      }
    }

    const r = RETOS_AP[idx];
    document.getElementById('rap-titulo').textContent = r.nombre;
    document.getElementById('rap-datos').innerHTML = r.medidas
      .map(m => `<span style="background:#e2e8f0; color:#0f172a; padding:3px 9px; border-radius:5px; font-size:0.86rem;">${m}</span>`)
      .join('');
    document.getElementById('rap-pista-box').innerHTML = r.pista;
    document.getElementById('rap-lbl-per').textContent = r.lblPer;
    document.getElementById('rap-lbl-area').textContent = r.lblArea;
    document.getElementById('rap-inp-per').value = '';
    document.getElementById('rap-inp-area').value = '';
    document.getElementById('rap-inp-per').style.borderColor = '#cbd5e1';
    document.getElementById('rap-inp-area').style.borderColor = '#cbd5e1';
    document.getElementById('rap-feedback').textContent = '';

    dibujarFiguraRetoAP(idx);
  };

  window.togglePistaFormula = function() {
    pistaVisible = !pistaVisible;
    document.getElementById('rap-pista-box').style.display = pistaVisible ? 'block' : 'none';
    document.getElementById('btn-pista-formula').textContent = pistaVisible ? 'Ocultar fórmula' : 'Ver fórmula';
  };

  function svgLabel(x, y, text, color, anchor) {
    return `<text x="${x}" y="${y}" text-anchor="${anchor || 'middle'}" font-size="13" font-weight="800" fill="${color}">${text}</text>`;
  }

  function dibujarFiguraRetoAP(idx) {
    const capa = document.getElementById('capa-reto-ap');
    capa.innerHTML = '';

    if (idx === 0) {
      // Cuadrado: lado azul (#0284c7) y etiqueta debajo en azul
      capa.innerHTML =
        `<rect x="125" y="55" width="110" height="110" fill="#e0f2fe" stroke="#0284c7" stroke-width="2.5"/>` +
        svgLabel(180, 188, 'l = 7 cm', '#0284c7', 'middle');

    } else if (idx === 1) {
      // Rectángulo: base abajo en verde (#16a34a) y altura marcada en naranja (#ea580c) a la derecha fuera del dibujo
      capa.innerHTML =
        `<rect x="85" y="75" width="150" height="80" fill="#dcfce7" stroke="#16a34a" stroke-width="2.5"/>` +
        `<line x1="235" y1="75" x2="235" y2="155" stroke="#ea580c" stroke-width="3"/>` +
        svgLabel(160, 178, 'b = 9 cm', '#16a34a', 'middle') +
        svgLabel(246, 120, 'h = 4 cm', '#ea580c', 'start');

    } else if (idx === 2) {
      // Triángulo: base inferior resaltada en verde (#16a34a) y altura interior discontinua en azul (#0284c7)
      // Etiqueta de altura fuera arriba-izquierda para no pisar el triángulo
      capa.innerHTML =
        `<polygon points="95,180 255,180 145,65" fill="#fef08a" stroke="#0f172a" stroke-width="2.5"/>` +
        `<line x1="95" y1="180" x2="255" y2="180" stroke="#16a34a" stroke-width="3.5"/>` +
        `<line x1="145" y1="65" x2="145" y2="180" stroke="#0284c7" stroke-width="2.5" stroke-dasharray="5,3"/>` +
        `<line x1="125" y1="95" x2="144" y2="112" stroke="#0284c7" stroke-width="1.2"/>` +
        svgLabel(175, 204, 'b = 8 cm', '#16a34a', 'middle') +
        svgLabel(122, 92, 'h = 6 cm', '#0284c7', 'end');

    } else if (idx === 3) {
      // Romboide: base abajo en azul (#0284c7), lado inclinado derecho en verde (#16a34a) y altura en naranja (#ea580c)
      capa.innerHTML =
        `<polygon points="75,180 205,180 245,85 115,85" fill="#e0f2fe" stroke="#0284c7" stroke-width="2.5"/>` +
        `<line x1="205" y1="180" x2="245" y2="85" stroke="#16a34a" stroke-width="3"/>` +
        `<line x1="115" y1="85" x2="115" y2="180" stroke="#ea580c" stroke-width="2.5" stroke-dasharray="5,3"/>` +
        `<line x1="88" y1="112" x2="114" y2="128" stroke="#ea580c" stroke-width="1.2"/>` +
        svgLabel(140, 204, 'b = 10 cm', '#0284c7', 'middle') +
        svgLabel(85, 110, 'h = 4 cm', '#ea580c', 'end') +
        svgLabel(234, 138, 'l = 5 cm', '#16a34a', 'start');

    } else if (idx === 4) {
      // Rombo: borde/lado en naranja (#ea580c), diagonal mayor en azul (#0284c7) y diagonal menor en verde (#16a34a)
      // Etiquetas fuera del rombo con línea guía fina hacia cada diagonal
      capa.innerHTML =
        `<polygon points="175,45 260,125 175,205 90,125" fill="#fff7ed" stroke="#ea580c" stroke-width="2.5"/>` +
        `<line x1="90" y1="125" x2="260" y2="125" stroke="#0284c7" stroke-width="2.2" stroke-dasharray="5,3"/>` +
        `<line x1="175" y1="45" x2="175" y2="205" stroke="#16a34a" stroke-width="2.2" stroke-dasharray="5,3"/>` +
        `<line x1="230" y1="125" x2="272" y2="162" stroke="#0284c7" stroke-width="1.2"/>` +
        `<line x1="175" y1="72" x2="268" y2="52" stroke="#16a34a" stroke-width="1.2"/>` +
        svgLabel(272, 48, 'd = 6 cm', '#16a34a', 'start') +
        svgLabel(274, 174, 'D = 10 cm', '#0284c7', 'start') +
        svgLabel(115, 72, 'l = 5 cm', '#ea580c', 'end');

    } else {
      // Hexágono regular: lado en verde (#15803d) arriba, apotema en azul (#0284c7) con etiqueta fuera abajo-derecha
      const cx = 175, cy = 120, rad = 72;
      const verts = [];
      for (let i = 0; i < 6; i++) {
        const a = ((-90 + i * 60) * Math.PI) / 180;
        verts.push({ x: cx + rad * Math.cos(a), y: cy + rad * Math.sin(a) });
      }
      const midX = (verts[2].x + verts[3].x) / 2;
      const midY = (verts[2].y + verts[3].y) / 2;
      const ptsStr = verts.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');

      capa.innerHTML =
        `<polygon points="${ptsStr}" fill="#dcfce7" stroke="#15803d" stroke-width="2.5"/>` +
        `<line x1="${cx}" y1="${cy}" x2="${midX.toFixed(1)}" y2="${midY.toFixed(1)}" stroke="#0284c7" stroke-width="2.5"/>` +
        `<circle cx="${cx}" cy="${cy}" r="3" fill="#0f172a"/>` +
        `<circle cx="${midX.toFixed(1)}" cy="${midY.toFixed(1)}" r="3" fill="#0284c7"/>` +
        `<line x1="${((cx + midX) / 2).toFixed(1)}" y1="${((cy + midY) / 2).toFixed(1)}" x2="255" y2="188" stroke="#0284c7" stroke-width="1.2"/>` +
        svgLabel(225, 62, 'l = 4 cm', '#15803d', 'start') +
        svgLabel(258, 195, 'ap = 3,5 cm', '#0284c7', 'start');
    }
  }

  window.comprobarRetoAP = function() {
    const r = RETOS_AP[idxAP];
    const vP = parseFloat(document.getElementById('rap-inp-per').value);
    const vA = parseFloat(document.getElementById('rap-inp-area').value);

    const okP = Math.abs(vP - r.per) < 0.01;
    const okA = Math.abs(vA - r.area) < 0.01;

    document.getElementById('rap-inp-per').style.borderColor = okP ? '#16a34a' : '#dc2626';
    document.getElementById('rap-inp-area').style.borderColor = okA ? '#16a34a' : '#dc2626';

    const fb = document.getElementById('rap-feedback');
    if (okP && okA) {
      fb.style.color = '#15803d';
      fb.textContent = `¡Muy bien! ${r.explicacion}`;
    } else {
      fb.style.color = '#dc2626';
      fb.textContent = 'Revisa los valores marcados en rojo: recuerda sumar todos los lados para el perímetro y aplicar la fórmula de área de la figura.';
    }
  };

  window.siguienteRetoAP = function() {
    cargarRetoAreaPer((idxAP + 1) % RETOS_AP.length);
  };

  cargarRetoAreaPer(0);
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
